//! operation 级 TypeScript server binding 与一次性业务模板。
//!
//! 绑定层只负责把 `operation_id` 映射到用户 handler，不复制执行器，也不 import
//! Hermes npm 包。业务模板只在缺失时创建，已存在则保留。

use crate::{
    bindings::Bindings,
    plan::{FileOwnership, GeneratedFile},
};

/// server 绑定生成路径。
pub(crate) const SERVER_PATH: &str = "hermes/server.ts";
/// 一次性业务模板路径。
pub(crate) const TEMPLATE_PATH: &str = "hermes/handlers.ts";

/// 渲染 server 绑定模块。
pub(crate) fn render(bindings: &Bindings) -> GeneratedFile {
    let mut out = String::new();
    out.push_str(
        "// Generated by `hermes-generator` from a `vos-operation-contract-v0` /\n\
         // `operation-syntax-projection` artifact. Do not edit by hand.\n",
    );

    if bindings.operations.is_empty() {
        out.push_str("\nexport {};\n");
    }
    else {
        let mut imports = Vec::with_capacity(bindings.operations.len() * 2);
        for operation in &bindings.operations {
            imports.push(operation.params_type());
            imports.push(operation.result_type());
        }
        out.push_str(&format!("\nimport type {{ {} }} from \"./operations\";\n", imports.join(", ")));
    }

    out.push_str(
        "\nexport interface HermesHandlerContext {\n\
         \x20 readonly operationId: string;\n\
         \x20 readonly deadline?: number;\n\
         \x20 readonly cancelled: boolean;\n\
         }\n\n",
    );

    out.push_str("export interface HermesOperationHandlers {\n");
    for operation in &bindings.operations {
        out.push_str(&format!(
            "  {}(ctx: HermesHandlerContext, params: {}): Promise<{}> | {};\n",
            operation.method_name,
            operation.params_type(),
            operation.result_type(),
            operation.result_type()
        ));
    }
    out.push_str("}\n\n");

    out.push_str(
        "export interface HermesOperationBinding {\n\
         \x20 readonly operationId: string;\n\
         \x20 readonly handler: (ctx: HermesHandlerContext, params: unknown) => unknown;\n\
         }\n\n",
    );

    out.push_str(
        "export function bindOperationHandlers(handlers: HermesOperationHandlers): HermesOperationBinding[] {\n\
         \x20 return [\n",
    );
    for operation in &bindings.operations {
        out.push_str(&format!(
            "    {{\n      operationId: \"{}\",\n      handler: (ctx, params) => handlers.{}(ctx, params as {}),\n    }},\n",
            operation.operation_id,
            operation.method_name,
            operation.params_type()
        ));
    }
    out.push_str("  ];\n}\n");

    GeneratedFile::new(SERVER_PATH, out, FileOwnership::Generated)
}

/// 渲染一次性业务模板。
pub(crate) fn render_template(bindings: &Bindings) -> GeneratedFile {
    let mut out = String::new();
    out.push_str(
        "// Created once by `hermes-generator`. This file is never overwritten.\n\
         // Implement each operation here; generated bindings only route by `operation_id`.\n\n",
    );

    if bindings.operations.is_empty() {
        out.push_str("export {};\n");
        return GeneratedFile::new(TEMPLATE_PATH, out, FileOwnership::Template);
    }

    out.push_str("import type { HermesOperationHandlers } from \"./server\";\n\n");
    out.push_str("export const handlers: HermesOperationHandlers = {\n");
    for operation in &bindings.operations {
        out.push_str(&format!(
            "  {}: async () => {{\n    throw new Error(\"operation `{}` is not implemented\");\n  }},\n",
            operation.method_name, operation.raw_name
        ));
    }
    out.push_str("};\n");

    GeneratedFile::new(TEMPLATE_PATH, out, FileOwnership::Template)
}
